// BAD: Improper use of Java API (SQL injection via string concatenation, and unsafe deserialization)
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class UserProfileServlet extends HttpServlet {
    // Simulated vulnerable endpoint
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String userId = req.getParameter("userId"); // user-controlled input
        String payload = req.getParameter("payload"); // user-controlled serialized bytes (Base64)

        // 1) SQL Injection: vulnerable use of Statement with concatenated input
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
             Statement stmt = conn.createStatement()) {

            // vulnerable: attacker can inject ' OR '1'='1 or ; DROP TABLE ...
            String sql = "SELECT username, email FROM users WHERE id = '" + userId + "'";
            ResultSet rs = stmt.executeQuery(sql);

            while (rs.next()) {
                resp.getWriter().println("User: " + rs.getString("username") + " Email: " + rs.getString("email"));
            }
        } catch (SQLException e) {
            resp.getWriter().println("DB error");
        }

        // 2) Insecure deserialization: directly deserializing untrusted data
        if (payload != null) {
            try {
                byte[] data = java.util.Base64.getDecoder().decode(payload);
                ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data));
                // vulnerable: may trigger gadget chains leading to RCE
                Object obj = ois.readObject();
                ois.close();
                resp.getWriter().println("Deserialized: " + obj.toString());
            } catch (Exception e) {
                resp.getWriter().println("Deserialize error");
            }
        }
    }
}
***
/*
GOOD: Safe use of Java APIs
- Use PreparedStatement with parameter binding to prevent SQL injection
- Avoid deserializing untrusted data; use safe formats (JSON) with strict validation
- Validate and constrain inputs
*/
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import com.fasterxml.jackson.databind.*;

public class SafeUserProfileServlet extends HttpServlet {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String userId = req.getParameter("userId");
        String json = req.getParameter("json"); // safe alternative to raw serialization

        // Validate userId: numeric and bounded length
        if (userId == null || !userId.matches("\\d{1,10}")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid userId");
            return;
        }

        // 1) SQL Injection prevention: use PreparedStatement
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT username, email FROM users WHERE id = ?")) {

            ps.setLong(1, Long.parseLong(userId));
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    resp.getWriter().println("User: " + rs.getString("username") +
                                             " Email: " + rs.getString("email"));
                }
            }
        } catch (SQLException e) {
            // Avoid leaking internals
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Database error");
            return;
        }

        // 2) Avoid insecure deserialization: use JSON with a strict DTO
        if (json != null) {
            try {
                // Define a strict DTO rather than Object
                UserPayload payload = MAPPER.readValue(json, UserPayload.class);
                // Additional validation
                if (payload.action == null || !payload.action.matches("[A-Za-z_]{1,32}")) {
                    resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid action");
                    return;
                }
                resp.getWriter().println("Received action: " + payload.action);
            } catch (Exception e) {
                resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid JSON");
            }
        }
    }

    // Strict DTO prevents polymorphic/gadget deserialization
    public static class UserPayload {
        public String action;
    }
}

