// BAD: Improper use of Java API leading to SQL Injection vulnerability
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletBad extends HttpServlet {
    // Simulated DataSource getter (for brevity)
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String username = req.getParameter("username"); // user-controlled
        String password = req.getParameter("password"); // user-controlled

        // BAD: Building SQL with string concatenation from user input is vulnerable
        String sql = "SELECT id, role FROM users WHERE username = '" + username
                   + "' AND password = '" + password + "'";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement(); // vulnerable pattern
             ResultSet rs = stmt.executeQuery(sql)) {  // untrusted input in query
            if (rs.next()) {
                // Authenticated (incorrectly, if injected)
                resp.setStatus(HttpServletResponse.SC_OK);
            } else {
                resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            }
        } catch (SQLException e) {
            // Leaks details if printed directly (additional risk)
            try { resp.sendError(500, "DB error: " + e.getMessage()); } catch (Exception ignore) {}
        }
    }
}

/*
Explanation:
- Using Statement and concatenating unvalidated user input into SQL enables SQL Injection.
- An attacker can set username to: 'admin' -- and bypass password checks, or use payloads like:
  ' OR '1'='1' -- to force a true predicate.
- Directly echoing exception messages may leak sensitive details.
*/

***
/*
GOOD: Use PreparedStatement with parameters, validate input, and avoid leaking internals.
Also, prefer secure password storage (hash + salt) instead of plain-text comparison.
*/
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.Optional;

public class LoginServletGood extends HttpServlet {
    // Simulated DataSource getter (for brevity)
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
    }

    // Minimal, example-only password checker; replace with strong hashing (e.g., BCrypt/Argon2)
    private boolean verifyPassword(char[] providedPassword, String storedHash) {
        // In real code, use a password hashing library and constant-time comparison.
        return MessageDigestIsPlaceholder.constantTimeEquals(
            PasswordHashingIsPlaceholder.hash(providedPassword), storedHash);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String username = Optional.ofNullable(req.getParameter("username")).orElse("");
        String password = Optional.ofNullable(req.getParameter("password")).orElse("");

        // Basic input sanity checks (length/charset); do not rely on this alone
        if (username.length() > 128 || password.length() > 1024) {
            sendSafeError(resp);
            return;
        }

        String sql = "SELECT id, role, password_hash FROM users WHERE username = ?";

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // GOOD: Parameterized query prevents injection by separating code and data
            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");
                    boolean ok = verifyPassword(password.toCharArray(), storedHash);
                    if (ok) {
                        resp.setStatus(HttpServletResponse.SC_OK);
                        return;
                    }
                }
                // Authentication failed without leaking which field was wrong
                resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            }
        } catch (SQLException e) {
            // Do not leak internal details; log server-side and send generic message
            sendSafeError(resp); // not vulnerable: avoids exposing stack traces or SQL
        }
    }

    private void sendSafeError(HttpServletResponse resp) {
        try { resp.sendError(500, "Unexpected error"); } catch (Exception ignore) {}
    }
}

/*
Explanation:
- PreparedStatement with placeholders (?) and ps.setString(...) prevents SQL Injection.
- Avoids concatenating user input into SQL, which was vulnerable in the bad example.
- Uses generic error responses to prevent information leakage.
- Real implementations must store password hashes and verify using a strong, salted algorithm.
*/

